import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 20 Pioneer pilots","description":"学习 过去将来时与计划结果，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 20 Pioneer pilots","description":"学习 过去将来时与计划结果，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 过去将来时与计划结果，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 19 A very dear cat","link":"/life/english/new-concept/book-3/unit-01/lesson-019"},"next":{"text":"第三册：培养技能 · Lesson 21 Daniel Mendoza","link":"/life/english/new-concept/book-3/unit-02/lesson-021"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 19 A very dear cat","link":"/life/english/new-concept/book-3/unit-01/lesson-019"},"next":{"text":"第三册：培养技能 · Lesson 21 Daniel Mendoza","link":"/life/english/new-concept/book-3/unit-02/lesson-021"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-020.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-020.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-020.md"};function l(r,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-20-pioneer-pilots" tabindex="-1">第三册：培养技能 · Lesson 20 Pioneer pilots <a class="header-anchor" href="#第三册-培养技能-·-lesson-20-pioneer-pilots" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 20 Pioneer pilots&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从早期飞行探索讨论目标、风险与准备，练习把过去某个时间点之后的计划写清楚。人物当时的希望不等于后来一定实现，复述时要保留这一差别。学习过去将来时描述计划和预期，并把后续实际结果另起句说明，形成准确的时间视角。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>pioneer</td><td>/ˌpaɪəˈnɪə/</td><td>n.</td><td>先驱</td><td>an aviation pioneer</td></tr><tr><td>attempt</td><td>/əˈtempt/</td><td>n.</td><td>尝试</td><td>a first attempt</td></tr><tr><td>fuel</td><td>/ˈfjuːəl/</td><td>n.</td><td>燃料</td><td>carry extra fuel</td></tr><tr><td>route</td><td>/ruːt/</td><td>n.</td><td>路线</td><td>plan a route</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take off — 飞机起飞，亦可指脱衣，需辨语境</li><li>set a record — 创造纪录</li></ul><h2 id="语法讲解-过去将来时与计划结果" tabindex="-1">语法讲解：过去将来时与计划结果 <a class="header-anchor" href="#语法讲解-过去将来时与计划结果" aria-label="Permalink to &quot;语法讲解：过去将来时与计划结果&quot;">​</a></h2><p>would 加动词原形可表示从过去看未来，常见于间接引语；was 或 were going to 也表示当时的计划或明显趋势。was to do 可用于安排或后来注定发生的事件，语域较书面。过去将来时本身不能证明计划实际完成，因此需要另一句交代结果。would 也可表示过去习惯或条件句结果，必须结合时间背景判断。写历史人物时，先建立“当时”这个观察点，再描述他们预计会发生什么，读者才不会把预期与事实混淆。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The pilot believed that the lighter engine would extend the aircraft&#39;s range.</p></blockquote><p>飞行员相信较轻的发动机会扩大飞机的航程。</p><p>believed 建立过去视点；would extend 指相对于相信时刻尚未发生的预期。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>He was going to fly at dawn 不保证他确实起飞；如果天气取消计划，原句仍然可以成立。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 was going to test 与 postponed，分别加重计划动词和结果动词，回听能否听出“预期—改变”的结构。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The team was going to test the glider on Monday. Strong winds made the hillside unsafe. They postponed the flight and inspected the frame instead.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构飞行试验记录，分别表达计划、阻碍和实际行动。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句为过去计划，后二句明确未按计划进行，时间逻辑完整。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句是否证明航程后来真的增加？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 它只报告飞行员当时的判断。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>转述：She said, “I will test the engine.”</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She said that she would test the engine.</p><p><strong>解析：</strong> 过去转述中 will 常后移为 would。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：They ___ going to leave before sunrise.（was/were）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> 主语 They 与 were 一致。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去将来时与计划结果。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-019">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-021">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
